# Finite, prespecified candidate grid. Confirmation never feeds candidate selection.
ds_is <- function(cfg)identical(cfg$research_family,"finite_design_search")
ds_names <- c(search="候选搜索/独立确认")
ds_candidates <- function(cfg){d<-cfg$candidate_table;keys<-c("label","n1","n2","stage1_day","max_day","landmark_age","w1");extra<-c("event_d1","event_d2");if(!is.data.frame(d)||!all(keys %in% names(d))||any(!names(d) %in% c(keys,extra))||nrow(d)<1||nrow(d)>20||anyNA(d)||anyDuplicated(d$label)||any(!nzchar(d$label)))stop("候选七列label,n1,n2,stage1_day,max_day,landmark_age,w1；事件模式另需event_d1/event_d2；1–20唯一名称。");if(mx_rule(cfg$base)=="target"&&!all(extra %in% names(d)))stop("事件驱动候选需event_d1,event_d2。");for(k in extra)if(!k %in% names(d))d[[k]]<-0;for(k in setdiff(names(d),"label"))if(!is.numeric(d[[k]])||any(!is.finite(d[[k]])))stop("候选参数需有限数值。");if(anyDuplicated(d[,setdiff(names(d),"label"),drop=FALSE]))stop("删除参数完全相同的重复候选。");d$CANDIDATE<-seq_len(nrow(d));d}
ds_scenarios <- function(cfg){c<-ds_candidates(cfg);t<-ma_scenarios(cfg$base);x<-expand.grid(TRUTH=t$SCENARIO,CANDIDATE=c$CANDIDATE,PHASE=c("discovery","confirmation"),KEEP.OUT.ATTRS=FALSE,stringsAsFactors=FALSE);x$label<-paste(x$PHASE,c$label[x$CANDIDATE],t$label[x$TRUTH],sep=" / ");x$SCENARIO<-seq_len(nrow(x));x}
ds_engine <- function(cfg,candidate){c<-cfg$base;r<-ds_candidates(cfg)[candidate,];for(k in c("n1","n2","stage1_day","max_day","landmark_age","w1","event_d1","event_d2"))c[[k]]<-r[[k]];c$seed<-cfg$seed;c$reps<-cfg$reps;c}
validate_design_search <- function(cfg){if(!ds_is(cfg)||!ma_is(cfg$base)||!ma_integer(cfg$reps,20,2000)||!ma_integer(cfg$seed,0,.Machine$integer.max)||!ma_scalar(cfg$power_target,.1,.999)||!ma_scalar(cfg$fwer_limit,.0001,.2)||!ma_scalar(cfg$confidence,.8,.999)||!ma_scalar(cfg$day_cost,0,1e5))stop("搜索需预定多臂基准；B20–2000、功效阈值0.1–0.999、FWER上限0.0001–0.2、MC置信度0.8–0.999、时间成本非负。");c<-ds_candidates(cfg);t<-ma_scenarios(cfg$base);if(nrow(t)>12)stop("搜索最多12个真值情景。");arms<-cfg$base$arms$arm[-1];hr<-as.matrix(t[,paste0("hr_",arms),drop=FALSE]);if(!any(apply(hr,1,function(x)all(x==1)))||!any(hr<1))stop("搜索至少含全HR=1零效应情景和真实有效臂情景；部分零效应情景也检查FWER。");for(j in c$CANDIDATE)validate_multiarm(ds_engine(cfg,j));sc<-ds_scenarios(cfg);if(nrow(sc)*cfg$reps>100000||sum(c$n1+c$n2)*nrow(t)*cfg$reps>1e7)stop("搜索/确认任务最多10万，预计患者×轮次最多1000万。");seeds<-unlist(lapply(sc$SCENARIO,function(j)vapply(seq_len(cfg$reps),function(b)batch_replicate_seed(cfg$seed,j,b),integer(1))),use.names=FALSE);if(anyDuplicated(seeds))stop("当前任务键派生种子存在重合，请调整规模。拒绝共用搜索/确认流。");invisible(TRUE)}
ds_cp <- function(k,n,delta,upper=FALSE){if(n<=0)return(if(upper)1 else 0);if(upper)if(k>=n)1 else qbeta(1-delta,k+1,n-k) else if(k<=0)0 else qbeta(delta,k,n-k+1)}
ds_metrics <- function(rows,cfg,phase="discovery",selected=NULL){sc<-ds_scenarios(cfg);tasks<-sc[sc$PHASE==phase,,drop=FALSE];if(phase=="confirmation"){if(is.null(selected)||is.na(selected))return(data.frame());tasks<-tasks[tasks$CANDIDATE==selected,,drop=FALSE]};arms<-cfg$base$arms$arm[-1];truth<-ma_scenarios(cfg$base);delta<-(1-cfg$confidence)/(2*if(phase=="discovery")nrow(ds_candidates(cfg))*nrow(truth) else nrow(truth));batch_bind_columns(lapply(seq_len(nrow(tasks)),function(i){s<-tasks[i,];d<-if(nrow(rows))rows[rows$SCENARIO==s$SCENARIO,,drop=FALSE] else rows;known<-if(nrow(d))d$decision_valid %in% TRUE else logical();n<-sum(known);kp<-if(n)sum(d$decision_reject[known] %in% TRUE) else 0;ke<-if(n)sum(d$fwer[known] %in% TRUE) else 0;h<-vapply(arms,function(g)truth[[paste0("hr_",g)]][s$TRUTH],numeric(1));pl<-ds_cp(kp,cfg$reps,delta);fu<-ds_cp(ke+cfg$reps-n,cfg$reps,delta,TRUE);data.frame(SCENARIO=s$SCENARIO,PHASE=phase,CANDIDATE=s$CANDIDATE,TRUTH=s$TRUTH,label=s$label,requested=cfg$reps,processed=nrow(d),valid=n,power_successes=kp,fwer_successes=ke,power_lower_all=kp/cfg$reps,fwer_upper_all=(ke+cfg$reps-n)/cfg$reps,power_cp_lower=pl,fwer_cp_upper=fu,require_power=any(h<1),require_fwer=any(h>=1),meets_power=if(any(h<1))pl>=cfg$power_target else TRUE,meets_fwer=if(any(h>=1))fu<=cfg$fwer_limit else TRUE,mc_tail_delta=delta,completed=nrow(d)==cfg$reps) }))}
ds_select <- function(rows,cfg){m<-ds_metrics(rows,cfg);c<-ds_candidates(cfg);complete<-nrow(m)>0&&all(m$completed);c$planned_cost<-c$n1+if(cfg$base$design=="final")0 else c$n2;c$planned_cost<-c$planned_cost+cfg$day_cost*if(cfg$base$design=="final")c$stage1_day else c$max_day;c$eligible<-vapply(c$CANDIDATE,function(j){d<-m[m$CANDIDATE==j,];complete&&all(d$meets_power&d$meets_fwer)},logical(1));good<-c[c$eligible,,drop=FALSE];selected<-if(nrow(good))good$CANDIDATE[order(good$planned_cost,good$n1+good$n2,good$CANDIDATE)][1] else NA_integer_;list(selected=selected,candidates=c,metrics=m,complete=complete,discovery_hash=batch_text_hash(batch_tree_text(if(nrow(rows))rows[rows$SCENARIO %in% ds_scenarios(cfg)$SCENARIO[ds_scenarios(cfg)$PHASE=="discovery"],,drop=FALSE] else data.frame())),rule="全部预定情景同时满足MC下界功效/上界FWER；最小预定成本，依次总N/候选ID打破平局")}
ds_trial <- function(cfg,sc,b,selection,keep_sample=FALSE){seed<-batch_replicate_seed(cfg$seed,sc$SCENARIO,b);if(sc$PHASE=="confirmation"&&(is.na(selection$selected)||sc$CANDIDATE!=selection$selected))return(list(row=data.frame(SCENARIO=sc$SCENARIO,SIMID=b,replicate_seed=seed,generated=FALSE,decision_valid=FALSE,decision_reject=NA,fwer=NA,structural_skip=TRUE,PHASE=sc$PHASE,CANDIDATE=sc$CANDIDATE,TRUTH=sc$TRUTH,note="未选候选不生成确认样本；不是生成失败。"),method_rows=data.frame(SCENARIO=sc$SCENARIO,SIMID=b,method="search",generated=FALSE,decision_valid=FALSE,decision_reject=NA,fwer=NA,action="not_selected"),looks=data.frame(),draw_rows=data.frame()));engine<-ds_engine(cfg,sc$CANDIDATE);t<-ma_scenarios(engine)[sc$TRUTH,,drop=FALSE];t$SCENARIO<-sc$SCENARIO;out<-ma_trial(engine,t,b,NULL,keep_sample);out$method_rows$method<-"search";out$row$PHASE<-sc$PHASE;out$row$CANDIDATE<-sc$CANDIDATE;out$row$TRUTH<-sc$TRUTH;out$row$structural_skip<-FALSE;out}
ds_aggregate <- function(s){cfg<-s$config;selection<-s$prepared$selection %||% ds_select(s$rows,cfg);s$overview<-ds_metrics(s$rows,cfg,"discovery");s$confirmation_overview<-ds_metrics(s$rows,cfg,"confirmation",selection$selected);s$candidate_overview<-selection$candidates;s$confirmation_decision<-data.frame(selected_candidate=selection$selected,confirmation_complete=if(nrow(s$confirmation_overview))all(s$confirmation_overview$completed) else FALSE,confirmation_passed=if(nrow(s$confirmation_overview)&&all(s$confirmation_overview$completed))all(s$confirmation_overview$meets_power&s$confirmation_overview$meets_fwer) else NA,selection_changed_by_confirmation=FALSE);s$selection_record<-data.frame(discovery_complete=selection$complete,selected_candidate=selection$selected,discovery_hash=selection$discovery_hash,rule=selection$rule,confirmation_used_for_selection=FALSE);s$method_overview<-s$overview;s$method_pairs<-s$resources<-s$stops<-s$comparisons<-s$candidates<-s$policy_overview<-s$gs_plans<-data.frame();s$arm_overview<-data.frame();mx_attach(s)}
ds_initial <- function(cfg,initial=NULL)ds_aggregate(list(config=cfg,scenarios=ds_scenarios(cfg),rows=initial$rows %||% data.frame(),method_rows=initial$method_rows %||% data.frame(),looks=initial$looks %||% data.frame(),draw_rows=initial$draw_rows %||% data.frame(),prepared=initial$prepared,completed=initial$completed %||% 0L,total=nrow(ds_scenarios(cfg))*cfg$reps,version=batch_version,status="running",review_status="pending_v0.35_review",dependencies=batch_dependencies(cfg),source_hash=batch_source_hash()))
ds_validate_saved <- function(s,cfg){if(!is.null(s$prepared$selection)){a<-ds_select(s$rows,cfg);if(!a$complete||!identical(a$selected,s$prepared$selection$selected)||!identical(a$discovery_hash,s$prepared$selection$discovery_hash))stop("搜索选择记录与冻结搜索样本不一致。")};invisible(TRUE)}
run_design_search <- function(cfg,progress=function(s)NULL,should_cancel=function()FALSE,replay_keys=NULL,resume_state=NULL,continuation_operation="resume"){validate_design_search(cfg);if(continuation_operation=="extend")stop("搜索/确认结果不追加B，以免改变已冻结选择。请创建新的搜索研究。");if(!is.null(resume_state))batch_validate_continuation(resume_state,cfg,continuation_operation);if(!is.null(resume_state)&&!is.null(replay_keys))stop("重放和续跑不能同时使用。");state<-ds_initial(cfg,resume_state);state$created_at<-resume_state$created_at %||% format(Sys.time(),tz="UTC",usetz=TRUE);state$schema<-"event_pred.batch_research.v4";state$initial_completed<-state$completed;state$continuation_operation<-if(is.null(resume_state))"new" else continuation_operation;handled<-matrix(FALSE,nrow(state$scenarios),cfg$reps);if(nrow(state$rows))handled[cbind(state$rows$SCENARIO,state$rows$SIMID)]<-TRUE;next_publish<-Sys.time();cancelled<-FALSE
  snap<-function(status){state$status<-status;ds_aggregate(state)};progress(snap("running"));for(j in seq_len(nrow(state$scenarios))){sc<-state$scenarios[j,,drop=FALSE];if(sc$PHASE=="confirmation"&&is.null(state$prepared$selection)){selection<-ds_select(state$rows,cfg);if(!selection$complete)break;state$prepared<-list(selection=selection);progress(snap("running"))};for(b in seq_len(cfg$reps)){if(handled[j,b])next;if(!is.null(replay_keys)&&!any(replay_keys$SCENARIO==j&replay_keys$SIMID==b))next;if(should_cancel()){cancelled<-TRUE;break};a<-ds_trial(cfg,sc,b,state$prepared$selection);for(k in c("rows","method_rows","looks","draw_rows")){key<-if(k=="rows")"row" else k;state[[k]]<-batch_bind_columns(list(state[[k]],a[[key]] %||% data.frame()))};state$completed<-state$completed+1L;handled[j,b]<-TRUE;if(Sys.time()>=next_publish||b==cfg$reps){progress(snap("running"));next_publish<-Sys.time()+2}};if(cancelled)break};snap(if(cancelled)"cancelled" else if(state$completed==state$total)"complete" else "partial_replay")}
ds_sample <- function(r,scenario,replicate){sc<-r$scenarios[r$scenarios$SCENARIO==scenario,,drop=FALSE];if(!any(r$rows$SCENARIO==scenario&r$rows$SIMID==replicate&r$rows$generated))stop("选择实际生成的搜索或确认轮次。");ds_trial(r$config,sc,replicate,r$prepared$selection,TRUE)}
ds_report <- function(r)c("# 预定候选搜索与独立确认开发稿",paste0("版本",r$version,"；B每任务",r$config$reps),"候选可预定固定日历上限或D1/D2事件目标；阶段目标未达p=1，成本按预定计划和日历上限。仅搜索阶段参与选择；确认用独立任务键/随机流，只生成已冻结候选。不满足搜索门槛时不强选。确认失败时保留该候选及失败结论，不回看确认结果重新择优。MC界为预定候选/情景家族的单侧Clopper-Pearson界，未知轮次按功效失败/FWER成功处理。界控制Monte Carlo不确定性，不能替代检验理论或数值验证。搜索不能追加B，需新建研究。",capture.output(print(r$selection_record,row.names=FALSE)),capture.output(print(r$candidate_overview,row.names=FALSE)),capture.output(print(r$confirmation_overview,row.names=FALSE)),"待验证。")
